-- GENERATED by tools\Make-UpdateNotes.ps1 from README.md - do not edit by hand.
-- What each pfUI Octo version brought: { version, { { title, text }, ... } }, newest first.
-- updatenotify.lua shows them in the update window and sends the titles to older versions.
pfUI.octoNotes = {
  { "1.2.38", {
    { "Honor tab rebuilt, battle-worn", "your PvP tab now has the battleground scene behind it, worn and burnt, with a big faction crest and your rank badge. A big rank progress bar (0 / 25 / 50 / 75 / 100 with glowing marks, today's gain lit) shows your exact rank %, and under it about how much honor the next rank still takes, learnt from your own kills at your rank. This week shows your honor against the 20 000 cap with the reset countdown and your session's honor per hour. Kills and honor for today / yesterday / this week / last week, and your last days in one tidy table: honor, kills, battlegrounds won-lost and rank % gained (hover a day for where the honor came from)." },
    { "Honor history built in (HonorSpy merged)", "every honor gain, battleground win / loss and step of rank % is kept per character. If you use TurtleHonorSpyEnhanced, its history is copied in once so your past days show straight away. /honor opens the tab. Options: Quality of Life > Honor." },
    { "Character window in the same look", "worn and burnt edges on every tab, your faction's crest glowing behind your character, your name in gold with your rank badge, a soft glow round rare and better gear, and worn panels under the stats. All of it can be switched off (Quality of Life > Honor > Character window)." },
    { "New pictures and files: restart the game, not just /reload", "" },
  } },
  { "1.2.37", {
    { "Minimap glow, even all the way round", "a new Glow card on Minimap > Map. Our own glows are drawn from the map's exact shape, so they sit evenly round every shape (the game's glow pictures used to sit further out on one side). 7 styles (Soft, Tight, Wide, Neon line, Halo ring, Double ring, Inner glow), colour from your own pick, class, accent, shifting between two colours or rainbow, animations (Pulse, Breathe, Heartbeat, Flicker, a Running light round the round map) with speed and how far it dims, a combat colour, show only in / out of combat, a flash when the map is pinged, and a Normal blend for a dark drop shadow. Six new looks: Soft glow, Neon accent, Halo breathing, Running light, Rainbow neon, Square soft shadow. New pictures: restart the game, not just /reload." },
    { "pfQuest load errors are caught", "if part of pfQuest fails while the game loads, chat says so at login with the first error in red (also saved for bug reports), and a half-loaded quest tracker is switched off instead of spamming tracker.lua errors." },
  } },
  { "1.2.36", {
    { "Installer once per character", "the installer now only shows the first time you log in on a new character. Finish it, skip it or close it and it never comes back by itself - not after updates either. Characters that already went through it are not asked again. Run it any time with /pfui install." },
    { "Minimap button in the addon bar", "with the addon button bar switched on, the pfUI Octo minimap button goes into it like every other add-on's button." },
  } },
  { "1.2.35", {
    { "pfUI Octo minimap button", "click it to open the options, right-click to move frames, drag it round the map. Switch it off under Quality of Life > Map and tooltips." },
    { "pfUI button stays in the Esc menu", "with the Game Menu skin switched off, the \"pfUI Config\" button used to vanish too. It is now always there." },
    { "Installer only at login", "closing the installer with its X made it come back after every loading screen. It now only asks again at your next login or reload. Thanks Barbeque_Squirrel for both reports!" },
  } },
  { "1.2.34", {
    { "No more quest tracker error spam", "the built-in quest tracker can no longer fill your screen with \"tracker.lua:282\" errors if pfQuest's helper table is missing - it now just uses the game's own quest watch window. If you saw this error, also make sure you are on the latest version. Thanks Mr_Rosh for the report!" },
  } },
  { "1.2.33", {
    { "Auto Shot in the right colour", "combat text showed Auto Shot (and wand / throw shots) in the yellow of \"Your spells\", whatever colour you set. They now use \"Your melee and Auto Shot\", as the setting says. Thanks Javelin!" },
    { "Hex codes and a Default button on every colour", "the colour picker now has a box where you can type a colour like #ff8800 (it also shows the code of the colour picked), and a Default button that puts that setting back to its original colour. Right-click any colour square to reset it straight away. Thanks Javelin for the idea!" },
  } },
  { "1.2.32", {
    { "Spells drag off your bars again", "if the built-in SuperCleveRoidMacros does not load fully on your PC, it now hands everything back to the game when it switches off - moving spells, /cast and /use work as normal, and pfUI's own macro handling takes over. Its chat line now shows the real error, so it can be fixed for good. Thanks DaddyWeeds for the report!" },
    { "\"Already built in\" check knows more add-ons", "at login pfUI Octo now also offers to switch off aux, Auctionator, TurtleMail, Postal, CT_MailMod, LazyPig, DPSMate, Details, KLHThreatMeter, MikScrollingBattleText, OneBag, SwingTimer and consume trackers - all built in already. Thanks Wolfahrt!" },
  } },
  { "1.2.31", {
    { "Map ping in the right place", "after using the world map zoom, the ping that marks you when the map opens could show up somewhere else. It now always lands on your arrow, zoomed in or not. Thanks mechanism for the report!" },
  } },
  { "1.2.30", {
    { "See everyone on the realm running pfUI Octo", "every pfUI Octo now joins the hidden realm channel at login and says its version there. The About page's \"online now\" counts everyone in that channel - the whole realm, older versions (1.2.16 on) included - and hovering it shows who and which version (older ones in red)." },
    { "Update popup from anywhere on the realm", "a newer version heard on the channel opens the update window, not only one heard in your guild or group. When someone older logs in, one player with a newer version answers them, so they find out at once - the channel stays quiet otherwise and never shows in chat. Switch it off with Minigames > \"Share on the realm channel\"." },
  } },
  { "1.2.29", {
    { "Left chat no longer goes blank", "when you shut the right window with the arrow at the bottom right: Loot & Spam moves into the left chat as a tab and General stays on screen (both windows got hidden before). If the left chat's picked window is ever hidden by something else, it comes back within a second." },
  } },
  { "1.2.28", {
    { "OctoRinse, five new looks", "Timer bars (each row drains as its debuff runs out, seconds on the icon), Health bars (rows filled with the player's health in their class colour - save the one who is dying), Spotlight (the next cure large on top, the rest slim), Calm (soft colours, no pulse or sound, rows stay put) and Tiles (big icons in rows, set the Columns)." },
    { "OctoRinse, less stress", "new card Order and calm - sort by lowest health or shortest time left, Rows stay put (nothing jumps under your mouse), Out of range at the bottom, and seconds left on the icons in any look." },
    { "OctoRinse and the DoT tracker read less", "a player's (or mob's) debuffs are only read again when the game says they changed (ClassicAPI GUID events for the DoT tracker), with a safety read every 1-2 s. OctoRinse no longer reads all 40 raiders four times a second, and its loop runs 30 times a second instead of every frame. In encounters it reads the bosses from the new boss1-boss5 units." },
    { "Action bars", "with ClassicAPI only the buttons whose usable state changed are redone (it was every button on every mana tick), cooldowns are only redrawn for buttons whose cooldown changed (it was every button on every global cooldown), and Shift / Ctrl / Alt page switching waits for a key change instead of looking every frame." },
    { "Raid frames", "the aggro glow / square is one shared pass a second (it walked ~190 unit names for each frame, ~7,600 checks a second in a raid), heal prediction 10 times a second like the bars, and the raid sorter sleeps outside a raid." },
    { "Timers everywhere", "buff timers and cooldown numbers only rebuild their text when the shown time changes; the player frame's aura swipes only restart when the aura changes." },
    { "The game's own world frame script", "no longer looks over its popups every frame while the interface is showing (Settings Performance Lighter world frame script). Minimap art only spins its loop while something spins." },
  } },
  { "1.2.27", {
    { "No more 1 FPS in raids with lots of add-ons", "when your add-ons together hold more memory than the ceiling (Settings Performance), the out-of-memory guard ran a full clean-up every second - the game froze again and again. Now the ceiling follows what is really in use, a forced clean-up runs at most once every 30 seconds, and you get one chat line saying how much memory your add-ons hold." },
  } },
  { "1.2.26", {
    { "Threat % on your target frame", "Meters Threat Label Where On my target frame puts just your threat % on top of your target frame (pfUI's, or the game's own), moving and sizing with it - no meter window needed. X / Y nudge it." },
  } },
  { "1.2.25", {
    { "Smoother raids, round three - threat", "the \"DoTs on the way\" countdown read every debuff on the boss about 25 times a second; now 4 times, with your DoTs' time left still exact. Your threat judgement (cap, colours, aggro countdown) is worked out once a tenth of a second and shared by the label, the popups and the window, and everyone's countdowns only when new numbers arrive." },
    { "Raid and party frames", "bars and texts redraw at most 10 times a second (up to 40 frames all changing in a raid fight); your own and your target's stay at 20." },
  } },
  { "1.2.24", {
    { "Smoother raids, round two - unit frames", "on a raid boss the target frame redrew on every aura and health change, many times a second. Every unit frame (target, raid, party...) now redraws its auras at most 10 times a second and its bars and texts at most 20 - still quicker than the eye, with no change ever lost." },
    { "Debuff timers read only what changed", "the target's debuffs are only read in full for the slots whose icon changed (usually none on a boss), with a full look on a new target and every 2 seconds." },
    { "Threat window", "redraws at most every 0.15 s - the server's numbers come about 5 times a second anyway." },
  } },
  { "1.2.23", {
    { "Smoother raids - threat", "in a raid the server's threat answers reach everyone, dozens a second, and each one was read and drawn. Now the first is shown at once, a burst is read as one, and the threat window redraws at most 10 times a second. Far less work and far less memory churn, with the same quick numbers." },
    { "Lighter debuff tracking", "DoT tick lines get a quick check before the full match, your target's debuffs are read at most 5 times a second (at once on a new target), and your own spell lines are only checked while a cast is pending." },
    { "OctoRinse in raids", "debuff changes rescan at most 10 times a second in a raid (20 in a group) - cures still show almost instantly." },
  } },
  { "1.2.22", {
    { "Meters stay the size you drag them to", "the threat window and every meter window keep whatever size you give them with the grip - through fights and reloads. They no longer shrink back to the lines they show (a single line when there is no fight)." },
    { "Tiny windows come back", "a window that was saved shrunk to a line or two comes back once at the normal size, ready to drag. \"Fit the lines\" is still in Meters > Data for anyone who likes it, now off by default." },
  } },
  { "1.2.21", {
    { "Meters resize where they are", "resizing the threat window or any meter window no longer throws it to the top-left corner of the screen. It stays put and grows or shrinks from its top-left corner, and is saved right there." },
  } },
  { "1.2.20", {
    { "Fair leaderboards - the same for everyone", "the settings that changed scores are gone. Normal, Heroic and Mythic always use every category, every aim round is 30 seconds and every target is the same size, so a score on the board means the same thing for every player." },
    { "Practice is just practice", "no clock and every category. Your best streak still shows there, but it is no longer a board, since with no clock it is not a contest. Scores now has 9 boards: Normal, Heroic, Mythic and the six aim modes." },
    { "Flight launcher", "the quiz card shows your best score on your hardest difficulty (for example \"MYTHIC BEST 52000\")." },
  } },
  { "1.2.19", {
    { "Top scores reach everyone on their own", "a new best goes out to every player on the realm with pfUI Octo a few seconds after you set it - quiz runs, aim modes and the practice streak, with your realm tag." },
    { "Log in to full boards", "when you log in, one player who is online sends you the top 3 of every board, so your Scores are filled straight away. Everyone else hears it too, so all boards stay in step, and only one player answers so the channel stays quiet." },
    { "Live boards", "an open Scores tab or quiz lobby updates the moment a score comes in. It all runs over the hidden OctoArcade channel; switch it off in Minigames > Scores." },
  } },
  { "1.2.18", {
    { "Quiz: Normal, Heroic and Mythic", "timed runs of 10, 25 and 40 questions (20, 15 and 10 seconds each). Faster answers score more - up to 1000 points in the first second, down to 250 at the buzzer, x1.5 on Heroic, x2 on Mythic, and up to +50% for a streak. Quiz-show look: countdown, live clock, A-D answers, a dot for every question, and a results card with a grade and the leaderboard. The old endless quiz is still there as Practice." },
    { "New leaderboards", "every board in one clean list - the three quiz runs, the six aim modes and the practice streak - with gold, silver and bronze for the top three and your own place always shown." },
    { "Realm tags", "every score shows the player's realm - NZ N'zoth, YS Y'Shaarj, CT C'thun. Players on older versions can't read the new scores until they update." },
    { "Flight launcher", "the sweep of light stays inside the sign, with a softer glow that lights up the title as it passes." },
  } },
  { "1.2.17", {
    { "New flight launcher", "an arcade marquee - a lit OCTO ARCADE sign with Darkmoon tickets, chasing bulbs and a sweep of light, a blinking INSERT COIN line, and three game cards (Quiz, Aim Trainer, High Scores) with glowing icons and live info: question count or your best streak, your top aim score, how many scores are on the board. It slides in, can be dragged anywhere, and remembers where you put it." },
    { "Flight bar", "the feather at the end of the bar no longer sits in a black square - it glows on the bar by itself." },
  } },
  { "1.2.16", {
    { "Aim trainer, arcade style", "modes on their own row (pick any mode at any time - a running round just stops), big stat panels, a timer bar that runs down, a scanline screen with glowing corners, 3-2-1-GO!, hit bursts, combo callouts (ON FIRE! x20, GODLIKE x50, BULLSEYE!, INTERRUPTED!), and a results card with a grade from S to D and a flashing NEW HIGH SCORE!" },
    { "Scores across the realm", "pfUI joins a hidden OctoArcade channel and says one short line with your bests once per login; everyone on the realm with pfUI Octo reads it into their Scores. You never see the channel in chat. Switch it off in Minigames Scores." },
  } },
  { "1.2.15", {
    { "OctoArcade - minigames for flights", "a small launcher pops up when a flight starts (or the game you pick opens by itself), and closes when you land. Also /arcade, /quiz, /aim, key bindings, and Quality of Life Minigames. Switch it off there or in the QoL Helpers list. New files: restart the game fully once." },
    { "Classic quiz", "660 questions of our own on lore, characters, places, dungeons, raids, classes, professions, items, PvP and the world - 10 categories you can switch on or off, a short \"did you know\" after many answers, streaks, and an optional timer." },
    { "Aim trainer, six modes", "Gridshot, Hexakill, Reflex, Precision (centre hits score more), Tracking (keep the mouse on a moving target) and Kick! (click the casters before their cast bar fills). Targets wear the other faction's faces, creatures, class pictures, raid marks or spell icons; results show accuracy, reaction time and best combo." },
    { "Scores shared between players", "bests go to your guild, group and battleground, and boards fill from the players they have met too." },
  } },
  { "1.2.14", {
    { "The Group Finder in pfUI's look", "OctoWoW's own group finder (Group Browser and Dungeon Finder), its role check, the \"your group is ready\" pop-up and the ready check window with the role circles now use pfUI's dark panels, buttons, tabs and bars instead of the game's wooden frames. The dungeon and role pictures stay. A new file, so restart the game fully (not just /reload)." },
  } },
  { "1.2.13", {
    { "Pick your parts when you install", "the installer has a new \"Which parts do you want?\" step. Click tiles to turn Meters, Combat Text, OctoDoTs, OctoRinse, the Auction House and 17 more on or off, or use All on / All off. Already installed? Run /pfui install to see it." },
    { "A tidier Send tab", "the money controls have their own panel, so nothing overlaps. A line under the amount says what will happen (\"They pay 5g for each of the 3 mails\"), and Clear and a bigger Send button sit in their own column." },
  } },
  { "1.2.12", {
    { "Breakdown reports work from every tab", "reporting the Summary or Deaths tab (a death log, for example) no longer gives a Lua error." },
    { "The Report menu is on top", "it opens over the breakdown window instead of behind it." },
  } },
  { "1.2.11", {
    { "Meter windows stay where you put them", "windows placed side by side (Damage Done and Threat, for example) no longer drift apart after a reload or when a window grows or shrinks to fit its lines. Each window is now saved by its top-left corner however you moved it: dragging, snapping, layout mode or resizing. Windows snapped before this come back where you dropped them." },
  } },
  { "1.2.10", {
    { "OctoProcs is taken out for now", "it no longer loads and its section is gone from the options, until it is ready. Your settings for it are kept, so it comes back as you left it." },
  } },
  { "1.2.9", {
    { "Auction lengths are this server's", "the Sell tab and the Auctions options show 6 h / 24 h / 72 h, as OctoWoW's own auction window does (they said 2 / 8 / 24, but your auctions always lasted the right time). The longest \"time left\" now reads \"over 8 h\"." },
    { "Exact deposit", "the deposit shown when you post is now the same sum the game's own auction window uses, per stack." },
    { "/db opens the database window again", "search items, mobs, objects and quests. /db help lists the commands." },
  } },
  { "1.2.8", {
    { "World map zoom fixed", "the spot under your cursor now stays put as you zoom in and out with the mouse wheel. Before, the map slid away from where you pointed." },
  } },
  { "1.2.7", {
    { "Zoom into the world map (Magnify built in)", "the mouse wheel zooms in where your cursor is (up to 4x), drag moves the view, and a new zone starts whole again. Quest pins, your arrow and your party zoom along. Steps aside if you run Magnify, Cartographer or MetaMap. Shift + wheel (opacity) and Ctrl + wheel (size) still work." },
    { "World buff timers", "when a head is handed in (Onyxia, Nefarian, Rend, Hakkar), a bar counts down to the buff landing, with its name, where it lands and the seconds left, plus a popup and a sound. Shared with your guild and group so you see it anywhere. /wb lists the last drops. A new file: restart the game fully once." },
  } },
  { "1.2.6", {
    { "Built-in SuperCleveRoidMacros and pfQuest step aside properly", "with your own separate SuperCleveRoidMacros or pfQuest switched on, pfUI's built-in copy now reliably stays out of the way, so the two never run together (that broke loading for some). If both ever load anyway, the separate one is switched off and chat asks for a /reload." },
    { "A folded whisper window stays folded", "it no longer pops open by itself when a fight ends. Only a window that folded itself for the fight opens again." },
  } },
  { "1.2.5", {
    { "No more \"IndexActionSlot\" error flood", "if the built-in SuperCleveRoidMacros does not load fully on your PC, it now switches itself off instead of erroring on every action bar change, and says once in chat what went wrong. Please send that line to the pfUI Octo Discord so it can be fixed for good." },
  } },
  { "1.2.4", {
    { "st_timer for your macros", "the swing timer fills st_timer and st_timerOff (seconds left on each hand's swing) like SP_SwingTimer / ST_Swingtimer, so Slam macros work without them." },
    { "Resistances as numbers", "enemy tooltips show \"Fire 75 (20%)\" - the resistance and the share of your spells it takes. QoL > Tooltips > \"Resists shown as\" picks numbers only or % only." },
    { "Line up with the market, like Aux", "on the Sell tab, click an auction under \"On the auction house now\" and your price goes just under it (the same as your own). A picked item now starts under the cheapest price on the auction house; Auctions > \"A picked item's price\" keeps your last price instead." },
  } },
  { "1.2.3", {
    { "Kill Command and other procs in combat text", "the moment a reactive spell can be cast it pops over you like a crit, with the flash - Kill Command, Arcane Surge, Surprise Attack, Baited Shot, Lacerate and Hammer of Wrath now, as well as Overpower, Revenge, Riposte, Counterattack and Mongoose Bite. No bar needed with ClassicAPI or nampower. Gold for new setups; set your own in Combat Text > Messages and sounds > \"Reactive skills and procs\"." },
  } },
  { "1.2.2", {
    { "No more target frame error", "\"TargetFrame.lua:291: attempt to index global 'Turtle_ChallengesCache'\" over and over on every target change is gone. The game's challenge lookup now always finds its table, even when the game's own saved data for it is missing." },
  } },
  { "1.2.1", {
    { "OctoProcs looks", "our own art - wings, a crown, a light beam, a ring and a glow - tinted in each proc's colour, with a burst as a proc starts. Pick a look for all or for each proc, plus its place and colour. ProcDoc's options are all there (least / most opacity and size, pulse speed, top and side offsets, mute, timers) and more: art size, countdown size, only in a fight, edge glow width. The hard light columns and solid screen bands are gone." },
    { "Tanks are never told to hold off", "Meters > Threat > Label & warnings starts with \"I am a tank\" (Auto / Always / Never). Auto counts holding aggro, Defensive Stance, Bear Form, Righteous Fury, Rockbiter or a tank mark, and stance dancing in a fight no longer wakes the warnings." },
    { "Threat label clears the auras", "on a nameplate it sits above the aura row instead of on it." },
    { "Overpower / Revenge alerts back", "combat text switches on the nampower events they need itself." },
    { "Minimap pins stay inside a round map,", "with the built-in or a separate pfQuest." },
    { "World map menus", "no more overlap with ModernMapMarkers, and the menus stay on screen when Magnify zooms in." },
    { "Demo mode", "Wipe, Enrage, Healers out of mana and the other lasting events light up while on and turn off with a second click; no more \"interval is empty\" error." },
  } },
  { "1.2.0", {
    { "OctoRinse sees your talents", "with ClassicAPI the range check is the same one your action bar uses, so talents that lengthen your cures' range count. Without it, each cure's range comes from its spell, or you set it yourself." },
    { "OctoRinse looks", "pfUI Octo, Bars (rows filled with the debuff school's colour), Bright (strong colour, a border and bigger words), Compact and Icons. Plus a school-colour border, an out-of-range fade setting and a pulsing top row." },
    { "OctoProcs", "big pulsing alerts round your character the moment a proc is up, with the spell icon, a glow, a countdown and stacks, an optional screen-edge glow and a sound. Under CoolDownManager, /procs." },
    { "Every nampower setting", "Settings > nampower has all of nampower's own options (spell queue, channels, safety, chat bubbles and more), each with its default and a reset." },
  } },
  { "1.1.99", {
    { "SuperCleveRoidMacros built in", "the newest SuperCleveRoidMacros now comes inside pfUI, nothing else to install. It needs ClassicAPI 1.15.8 or newer (the Octo DLL Installer puts it in). Your SCRM settings carry over." },
    { "Takes over your separate copy", "if you had SuperCleveRoidMacros installed, pfUI switches it off for your next login and says so in chat. Tick it again in the add-on list to keep yours - pfUI leaves it alone after that." },
    { "Conditional macros show right on the bars", "pfUI's action bars now leave macros to SuperCleveRoidMacros, so a button shows the spell, icon and cooldown it will really cast instead of the macro's first spell." },
  } },
}
